using System;using System.IO;using System.Text;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad]public static class EnglishDialogueAuditV08 {
  const string Key="ZTM_EN_DIALOGUE_V08";static GameView view;static RenderTexture rt;static int size,scenario,phase,warm,count,fail;static double at;static StringBuilder log=new StringBuilder();static string Root=>Directory.GetParent(Application.dataPath).FullName;static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
  static readonly int[] Widths={320,360,360,480},Heights={640,640,800,960};
  static EnglishDialogueAuditV08(){EditorApplication.update+=Tick;}
  public static void BatchStart(){SessionState.SetBool(Key+"batch",true);Start();}
  public static void Start(){Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","v08-dialogue-checks-2","save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
  static void Check(bool ok,string text){count++;if(!ok){fail++;log.AppendLine("FAIL size="+size+" scenario="+scenario+" "+text);}}
  static void Capture(){var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","v08-dialogue-"+Widths[size]+"x"+Heights[size]+"-"+scenario+".png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);RenderTexture.active=old;}
  static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;}
   if(phase==0){if(rt==null){rt=new RenderTexture(Widths[size],Heights[size],0,RenderTextureFormat.ARGB32);rt.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=rt;}
    var s=new PlayerState();if(scenario<5){if(scenario==1)s.tutorial.step=1;if(scenario==2){s.spins=1;s.tutorial.step=2;}if(scenario==3){s.cash=60;s.fragments[0]=20;}if(scenario==4)s.purchased[0]=true;}
    else{s.tutorial.completed=true;if(scenario<9){int[] masks={3,28,96,255};for(int i=0;i<8;i++)s.purchased[i]=(masks[scenario-5]&(1<<i))!=0;}}
    view.SetQaState(s,0);
    if(scenario>=9&&scenario<14){var d=(DialoguePresenter)typeof(GameView).GetField("dialogue",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(view);d.Replay();typeof(DialoguePresenter).GetField("replay",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(d,scenario-9);typeof(DialoguePresenter).GetField("lastMode",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(d,-99);typeof(DialoguePresenter).GetField("nextCheck",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(d,0f);d.Tick();}
    if(scenario==14)view.QaClick("menu");if(scenario==15)view.QaShowReset();warm=0;at=EditorApplication.timeSinceStartup;phase=1;
   }else if(phase==1&&++warm>24&&EditorApplication.timeSinceStartup-at>.35){
    if(scenario<14){var bubble=UI.Q<VisualElement>("heroine-dialogue");Check(bubble.resolvedStyle.display==DisplayStyle.Flex,"dialogue is visible");foreach(string name in new[]{"dialogue-title","dialogue-text"}){var l=UI.Q<Label>(name);var m=l.MeasureTextSize(l.text,l.contentRect.width,VisualElement.MeasureMode.AtMost,0,VisualElement.MeasureMode.Undefined);Check(m.y<=l.contentRect.height+1,"wrapped "+name+" height="+m.y+" available="+l.contentRect.height);Check(!System.Text.RegularExpressions.Regex.IsMatch(l.text,"[\\u0400-\\u04ff]"),"English text");}foreach(string name in new[]{"tutorial-next","tutorial-skip"}){var b=UI.Q<Button>(name);if(!UiInputCoordinator.IsShown(b))continue;Check(b.worldBound.width>=44&&b.worldBound.height>=44,"button touch size");var l=b.Q<Label>("button-caption");var m=l.MeasureTextSize(l.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);Check(m.x<=l.contentRect.width+1,"caption fits");}}
    else{var modal=UI.Q<VisualElement>(scenario==14?"settings":"reset-confirmation");Check(modal.worldBound.yMin>=0&&modal.worldBound.yMax<=UI.worldBound.yMax+1,"modal fits viewport");foreach(var l in modal.Query<Label>().ToList()){var m=l.MeasureTextSize(l.text,l.contentRect.width,VisualElement.MeasureMode.AtMost,0,VisualElement.MeasureMode.Undefined);Check(m.y<=l.contentRect.height+1,"modal text fits: "+l.text);}}
    if(size<2||scenario==14)Capture();log.AppendLine("CASE "+Widths[size]+"x"+Heights[size]+" "+scenario+" checked");if(++scenario<16){phase=0;return;}scenario=0;view.GetComponent<UIDocument>().panelSettings.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);rt=null;if(++size<4){phase=0;return;}log.AppendLine("RESULT "+(fail==0?"PASS":"FAIL")+" checks="+count+" failures="+fail+"; 64 actual layouts; all five tutorial steps/four stories/five replays/menu/reset; no OS input");Finish();}
  }catch(Exception e){log.AppendLine("FAIL "+e);Debug.LogException(e);Finish();}}
  static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","v08-dialogue-checks-2.txt"),log.ToString());if(rt!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);}EditorApplication.ExitPlaymode();if(SessionState.GetBool(Key+"batch",false))EditorApplication.delayCall+=()=>EditorApplication.Exit(0);}
 }
}
